import csv,json,glob,collections,itertools
from fractions import Fraction as F
from decimal import Decimal
ROOT='/app/'
def rows(f): return list(csv.DictReader(open(ROOT+f)))
def unit(x):
 v=Decimal(str(x))*10000
 assert v==int(v),x
 return int(v)
P={r['run_id']:r for r in rows('plan.csv')}; L={r['run_id']:r for r in rows('launch_log.csv')}; R={r['run_id']:r for r in rows('runtime.csv')}; D={r['run_id']:r for r in rows('retention_log.csv')}
Q=json.load(open(ROOT+'queries.json')); suites=json.load(open(ROOT+'suites.json')); policy=json.load(open(ROOT+'retention_policy.json'))['versions']
keys=['suite','curriculum','retrieval','decoder']
def config(p): return tuple(p[k] for k in keys)
C=collections.defaultdict(list)
for rid in L: C[config(P[rid])].append(rid)
bounds={}; kind={}
for rid,l in L.items():
 p=P[rid]; finish=R[rid]['finished_at']; s=suites[p['suite']]; floor=next(unit(v['floor']) for v in policy if v['from']<=finish<v['to'])
 lo=unit(s['random_guess']) if s['scoring']=='raw' else 0; hi=10000
 outage=(l['worker'] in ['w03','w07'] and '2026-06-27T00:00:00Z'<=l['started_at']<='2026-07-03T12:00:00Z') or (l['worker']=='w09' and '2026-07-11T00:00:00Z'<=l['started_at']<'2026-07-15T00:00:00Z')
 reason=D.get(rid,{}).get('reason')
 if reason=='below_retention_floor':
  assert not outage
  assert D[rid]['dropped_at']==finish
  hi=floor-1; kind[rid]='range'
 elif reason=='shard_file_lost':
  assert not outage
  lo=max(lo,floor);kind[rid]='value'
 elif outage: kind[rid]='no_bundle'
 else: lo=max(lo,floor);kind[rid]='value'
 bounds[rid]=[lo,hi]
def constrain(rid,lo,hi):
 if rid not in L:return
 b=bounds[rid]; b[0]=max(b[0],lo);b[1]=min(b[1],hi);assert b[0]<=b[1],(rid,b,lo,hi)
for r in rows('eval_results.csv'): constrain(r['run_id'],unit(r['pass_rate']),unit(r['pass_rate']))
for path in glob.glob(ROOT+'recovered/*.csv'):
 for r in csv.DictReader(open(path)):
  val=unit(Decimal(r['pass_rate_pct'])/100);constrain(r['run_id'],val,val)
width={'arc_lite':400,'gsm_plus':200,'code_ms':250}
for r in rows('recovery_log.csv'):
 rid=r['run_id'];assert kind[rid]==r['outcome']
 if r['outcome']!='no_bundle':
  lo,hi=unit(r['returned_lo']),unit(r['returned_hi'])
  assert hi-lo==(width[P[rid]['suite']] if kind[rid]=='range' else 0)
  constrain(rid,lo,hi)

def residual(rid):
 lo,hi=bounds[rid]
 return min(hi-lo, width[P[rid]['suite']] if kind[rid]=='range' else (0 if kind[rid]=='value' else hi-lo))

days=collections.defaultdict(list)
for rid in L:days[R[rid]['finished_at'][:10]].append(rid)
digest={r['date']:r for r in rows('daily_digest.csv')}
T={d:unit(r['sum_pass_rate']) for d,r in digest.items()}
for d,ids in days.items():
 assert len(ids)==int(digest[d]['n_runs'])
 assert sum(bounds[r][0] for r in ids)<=T[d]<=sum(bounds[r][1] for r in ids)
 print('DAY',d,'unknown',sum(bounds[r][0]!=bounds[r][1] for r in ids),'lower slack',T[d]-sum(bounds[r][0] for r in ids),'upper slack',sum(bounds[r][1] for r in ids)-T[d])

def coeff(q):
 a=collections.defaultdict(F)
 for side,sign in [('from',-1),('to',1)]:
  ids=C[config(q[side])]
  assert ids
  for rid in ids:a[rid]+=F(sign,len(ids))
 return a

def interval(q):
 a=coeff(q); vals=[]
 for sign in [1,-1]:
  total=F(0)
  for d,ids in days.items():
   slack=T[d]-sum(bounds[r][0] for r in ids)
   total+=sum((a[r]*bounds[r][0] for r in ids),F(0))
   for r in sorted(ids,key=lambda r:sign*a[r]):
    n=min(slack,bounds[r][1]-bounds[r][0]);total+=a[r]*n;slack-=n
   assert slack==0
  vals.append(total/10000)
 return vals

def guaranteed(q,S=()):
 a=coeff(q);S=set(S);total=F(0)
 for d,ids in days.items():
  B=min(T[d]-sum(bounds[r][0] for r in ids),sum(bounds[r][1] for r in ids)-T[d])
  caps=collections.defaultdict(int)
  for r in ids:caps[a[r]]+=residual(r) if r in S else bounds[r][1]-bounds[r][0]
  group=sorted((c,n) for c,n in caps.items() if n)
  if not group:continue
  i=0;j=len(group)-1;cap=[n for c,n in group]
  while i<j and B:
   n=min(cap[i],cap[j],B);total+=(group[j][0]-group[i][0])*n
   cap[i]-=n;cap[j]-=n;B-=n
   if cap[i]==0:i+=1
   if cap[j]==0:j-=1
