 print('VALUE',q['id'],float(before),float(after),A['values'][q['id']])
for q in Q['widths']: A['widths'][q['id']]=float(guaranteed(q,q['recover']))
for q in Q['plans']:
 # Daywise contributions permit caching by subsets, but these small candidate sets can be enumerated directly.
 target=F(str(q['target']));found=False
 for k in range(len(q['candidates'])+1):
  best=None
  for S in itertools.combinations(q['candidates'],k):
   w=guaranteed(q,S)
   if best is None or w<best:best=w
   if w<=target:
    A['plans'][q['id']]={'k':k,'runs':list(S)};found=True
    print('PLAN',q['id'],'k',k,'width',float(w),'set',S,flush=True);break
  if found:break
  print('PLAN minimum',q['id'],'k',k,'width',float(best),flush=True)
 assert found
print(json.dumps(A,indent=2))
with open(ROOT+'answers.json','w') as f:json.dump(A,f,indent=2);f.write('\n')
